import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { obtenerSucursalesOrdenadas, obtenerEstrellas } from '../data/mockDiscoveryDB';
import '../estilos/escritorio/principal.css';
import '../estilos/movil/responsivo.css';

/**
 * Inicio — V4: Premium Grid layout showing branches sorted by ranking.
 * Minimalist cards: Logo + Name + Star Rating only.
 */
const Inicio = () => {
    const [sucursales, setSucursales] = useState([]);

    useEffect(() => {
        setSucursales(obtenerSucursalesOrdenadas());
    }, []);

    // Render visual stars
    const renderEstrellas = (rating) => {
        const estrellas = obtenerEstrellas(rating);
        return (
            <div style={{ display: 'flex', gap: '2px', alignItems: 'center' }}>
                {estrellas.map((tipo, i) => (
                    <span key={i} style={{
                        fontSize: '0.9rem',
                        color: tipo === 'empty' ? '#334155' : '#f59e0b',
                        opacity: tipo === 'half' ? 0.6 : 1,
                    }}>
                        ★
                    </span>
                ))}
                <span style={{ color: '#94a3b8', fontSize: '0.8rem', marginLeft: '0.4rem', fontWeight: 500 }}>
                    {rating}
                </span>
            </div>
        );
    };

    return (
        <div style={{ backgroundColor: '#0f172a', minHeight: '100vh', color: '#f1f5f9', padding: '1.5rem' }}>
            <div style={{ maxWidth: '900px', margin: '0 auto' }}>

                {/* Hero */}
                <div style={{ textAlign: 'center', paddingTop: '1.5rem', marginBottom: '2rem' }}>
                    <h1 style={{ fontSize: '1.8rem', fontWeight: 800, marginBottom: '0.5rem' }}>
                        Terminal de Buses <span style={{ color: '#3b82f6' }}>Bolivia</span>
                    </h1>
                    <p style={{ color: '#64748b', fontSize: '0.95rem', marginBottom: '1.5rem' }}>
                        Las mejores empresas de transporte, calificadas por viajeros reales
                    </p>
                    <Link to="/buscar"
                        style={{
                            display: 'inline-flex', alignItems: 'center', gap: '0.5rem',
                            padding: '0.8rem 2rem', borderRadius: '12px',
                            background: 'linear-gradient(135deg, #3b82f6, #2563eb)',
                            color: 'white', textDecoration: 'none', fontWeight: 600, fontSize: '0.95rem',
                            boxShadow: '0 4px 14px rgba(59,130,246,0.35)',
                            transition: 'transform 0.2s, box-shadow 0.2s',
                        }}
                        id="btn-ir-buscador"
                    >
                        🔍 Buscar Viajes Disponibles
                    </Link>
                </div>

                {/* Section Title */}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
                    <h2 style={{ fontSize: '1.1rem', fontWeight: 600, color: '#94a3b8' }}>
                        Empresas Destacadas
                    </h2>
                    <span style={{ fontSize: '0.8rem', color: '#475569' }}>
                        Ordenadas por calificación
                    </span>
                </div>

                {/* Premium Grid */}
                <div style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))',
                    gap: '1rem',
                }}>
                    {sucursales.map((s, index) => (
                        <Link
                            key={s.id}
                            to={`/sucursal/${s.id}`}
                            style={{ textDecoration: 'none', color: 'inherit' }}
                        >
                            <div style={{
                                background: '#1e293b',
                                borderRadius: '14px',
                                padding: '1.5rem',
                                border: '1px solid #334155',
                                cursor: 'pointer',
                                transition: 'transform 0.2s, box-shadow 0.2s, border-color 0.2s',
                                position: 'relative',
                                overflow: 'hidden',
                            }}
                                onMouseEnter={e => {
                                    e.currentTarget.style.transform = 'translateY(-3px)';
                                    e.currentTarget.style.boxShadow = '0 8px 25px rgba(0,0,0,0.3)';
                                    e.currentTarget.style.borderColor = s.colorLogo || '#3b82f6';
                                }}
                                onMouseLeave={e => {
                                    e.currentTarget.style.transform = 'translateY(0)';
                                    e.currentTarget.style.boxShadow = 'none';
                                    e.currentTarget.style.borderColor = '#334155';
                                }}
                            >
                                {/* Rank badge */}
                                {index < 3 && (
                                    <div style={{
                                        position: 'absolute', top: '0.75rem', right: '0.75rem',
                                        background: index === 0 ? '#f59e0b' : index === 1 ? '#94a3b8' : '#cd7f32',
                                        color: '#0f172a', width: '26px', height: '26px',
                                        borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center',
                                        fontWeight: 800, fontSize: '0.75rem',
                                    }}>
                                        {index + 1}
                                    </div>
                                )}

                                {/* Logo */}
                                <div style={{
                                    width: '56px', height: '56px', borderRadius: '14px',
                                    background: `${s.colorLogo || '#3b82f6'}20`,
                                    border: `1px solid ${s.colorLogo || '#3b82f6'}40`,
                                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                                    fontSize: '1.8rem', marginBottom: '1rem',
                                }}>
                                    {s.logo}
                                </div>

                                {/* Name */}
                                <h3 style={{
                                    fontSize: '1.05rem', fontWeight: 700, marginBottom: '0.5rem',
                                    color: '#f1f5f9', margin: '0 0 0.5rem 0',
                                }}>
                                    {s.nombre}
                                </h3>

                                {/* Stars */}
                                {renderEstrellas(s.ranking)}
                            </div>
                        </Link>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default Inicio;
